INSERT INTO methodology_versions (id, version, changelog, config_json, is_current) VALUES ('49aac236-4daa-5dff-9931-9ac7c6612c84', '0.2.0', 'v0.2.0 adds Potential Outlook (a forward-looking but explicitly uncalibrated derived metric: how much of the unrealized promise current execution supports capturing — NOT a probability, NOT a price prediction) and a published observer-effect policy: the Clock acknowledges that publishing scores can itself move markets (reflexivity) and commits to safeguards — append-only history, versioned methodology, publisher holdings disclosure, no per-project tuning, no paid placement.', '{"categories":{"execution":{"description":"Smart-contract / execution layers are judged primarily on fee-generating usage and developer activity.","reality_weights":{"capital_committed":0.2,"developer_activity":0.15,"economic_throughput":0.35,"thesis_milestones":0.3}},"monetary":{"description":"Monetary assets are NOT judged primarily on protocol revenue. Milestone achievement (surviving cycles, institutional adoption) dominates; fees measure settlement demand.","reality_weights":{"capital_committed":0.1,"developer_activity":0.1,"economic_throughput":0.3,"thesis_milestones":0.5}},"oracle":{"description":"Oracle networks are judged on feed adoption and fee-paying data consumers; TVL is mostly irrelevant.","reality_weights":{"capital_committed":0.05,"developer_activity":0.15,"economic_throughput":0.25,"thesis_milestones":0.55}},"payments":{"description":"Payment rails are judged on settlement volume and institutional dependence; speculation-free usage matters most.","reality_weights":{"capital_committed":0.1,"developer_activity":0.1,"economic_throughput":0.3,"thesis_milestones":0.5}}},"changelog":"v0.2.0 adds Potential Outlook (a forward-looking but explicitly uncalibrated derived metric: how much of the unrealized promise current execution supports capturing \u2014 NOT a probability, NOT a price prediction) and a published observer-effect policy: the Clock acknowledges that publishing scores can itself move markets (reflexivity) and commits to safeguards \u2014 append-only history, versioned methodology, publisher holdings disclosure, no per-project tuning, no paid placement.","components":{"capital_committed":{"description":"How much capital is committed onchain (TVL). Log-scaled: $10M -> 0, $100B -> 10.","epistemic":"measured","metrics":["tvl_usd"],"missing":"renormalize_weights_and_reduce_confidence","name":"Capital committed","normalization":{"ceiling":100000000000,"floor":10000000,"type":"log_scale"}},"developer_activity":{"description":"Core-protocol development pace. CoinGecko developer_data in v0.1 (spotty upstream); dedicated GitHub adapter is Phase 2.","epistemic":"measured","metrics":["dev_commits_4w"],"missing":"renormalize_weights_and_reduce_confidence","name":"Developer activity","normalization":{"ceiling":3000,"floor":10,"type":"log_scale"}},"economic_throughput":{"description":"Trailing user-paid fee revenue, annualized. Fees are the hardest evidence of willingness to pay for blockspace.","epistemic":"measured","metrics":["fees_annualized_usd"],"missing":"renormalize_weights_and_reduce_confidence","name":"Economic throughput","normalization":{"ceiling":10000000000,"floor":100000,"type":"log_scale"}},"incentive_dependence":{"description":"Share of activity attributable to token incentives. No reliable Phase 1 source.","epistemic":"measured","metrics":[],"missing":"unavailable_in_v0_1","name":"Incentive dependence","normalization":{"type":"unavailable"}},"milestone_velocity":{"description":"Thesis milestones achieved in the trailing 3 years, scaled: 2+ milestones -> 10. Momentum, not just level.","epistemic":"modeling","metrics":[],"missing":"n/a","name":"Milestone velocity","normalization":{"cap_count":2,"type":"recent_count","window_years":3}},"necessity_inverse":{"description":"10 minus analyst-assessed Token Necessity. A token the protocol does not need is a reflexive-asset warning sign.","epistemic":"modeling","metrics":[],"missing":"n/a","name":"Token-necessity inverse","normalization":{"of_component":"token_necessity","type":"inverse_of"}},"setback_drag":{"description":"Major setbacks (outages, failed launches, lost flagship deals) in the trailing 3 years. Each setback subtracts 3 points from 10.","epistemic":"modeling","metrics":[],"missing":"n/a","name":"Setback drag","normalization":{"per_event_penalty":3,"type":"event_penalty","window_years":3}},"supply_overhang":{"description":"Share of fully-diluted value not yet circulating: (FDV - market cap) / FDV * 10. Future dilution is future sell pressure.","epistemic":"measured","metrics":["fdv_usd","market_cap_usd"],"missing":"renormalize_weights_and_reduce_confidence","name":"Supply overhang","normalization":{"type":"ratio_pct_of_fdv"}},"thesis_milestones":{"description":"Highest achieved rung (0-5) of the category milestone ladder, scaled to 0-10. Analyst-assessed against published evidence requirements.","epistemic":"modeling","metrics":[],"missing":"n/a","name":"Thesis milestones","normalization":{"max_level":5,"type":"ladder"}},"valuation_multiple":{"description":"log10(market_cap / annualized_fees), mapped so a 10x multiple -> 2 and a 100,000x multiple -> 10. Answers: how much of today''s value is explained by today''s economic activity?","epistemic":"measured","metrics":["market_cap_usd","fees_annualized_usd"],"missing":"renormalize_weights_and_reduce_confidence","name":"Valuation vs economic activity","normalization":{"log_ratio_100000x":10,"log_ratio_10x":2,"type":"log_ratio_map"}}},"confidence":{"clamp":[5,98],"dimensions":["reality","execution_evidence","reflexivity_risk","development"],"method":"100 * mean over dimensions of (available_weight_fraction * source_quality). Measured components have quality 1.0, analyst-assessed 0.75. Never claims 100%: the map is not the territory.","note":"Missing data reduces confidence. It never becomes zero silently, and it never gets invented.","provisional_threshold":40,"source_quality":{"measured":1.0,"modeling":0.75}},"created":"2026-09-19","derived":{"belief_gap":{"available":false,"formula":"community_reality - algorithmic_reality","note":"No community layer in v0.1 (Phase 3)."},"build_gap":{"available":true,"formula":"development - reality","note":"Positive: developers building faster than utility arrives. Promising or concerning depending on trajectory and Prove-It Age."},"hype_gap":{"available":false,"formula":"attention - reality","note":"Attention scoring is Phase 2 (no reliable source in v0.1)."},"promise_gap":{"available":true,"formula":"world_impact_potential - reality","note":"How much of the theoretical promise remains unrealized. One of the site''s most important numbers."},"potential_outlook":{"available":true,"formula":"clamp(max(promise_gap, 0) \u00d7 (execution_evidence / 10), 0, 10)","note":"Forward-looking, but NOT a probability and NOT a price prediction \u2014 uncalibrated until historical backtesting exists (same rule as Execution Evidence). Reads as: of the promise not yet realized, how much does current execution support capturing? Floored at 0: a negative promise gap means the thesis is already exceeded, leaving no unrealized promise to capture."}},"gates":[{"id":"economic_demand_floor","rationale":"A protocol with ~zero demonstrated willingness-to-pay cannot sit in the top Reality tiers no matter how loud the narrative.","then":"cap reality at 4.0","when":{"component":"economic_throughput","lt":2}},{"id":"token_necessity_gate","rationale":"If the protocol works essentially unchanged without its token, the token''s utility score cannot be high.","then":"cap token_value_capture at 4.0","when":{"assessment":"token_necessity","lt":3}},{"id":"provisional_flag","rationale":"Low-confidence numbers must be labeled, not hidden.","then":"all score statuses for the project become ''provisional''","when":{"confidence_lt":40}},{"id":"post_incentive_cap","inert_in_v0_1":true,"rationale":"Configured for Phase 2 when subsidy data exists. If >80% of activity disappears after incentives end, adoption components get capped.","then":"cap economic_throughput and thesis_milestones contributions at 50%","when":{"lt":0.2,"metric":"post_incentive_retention_180d"}}],"scores":{"attention":{"available_in_v0_1":false,"components":{},"description":"Mindshare: mentions, search, social. Phase 2 \u2014 no reliable source in v0.1.","epistemic":"measured","kind":"supporting","name":"Attention","scale":[0,10],"unavailable_reason":"No reliable attention data source in v0.1 (X/Reddit/Trends adapters are Phase 2). Marked unavailable; reduces confidence."},"development":{"available_in_v0_1":true,"components":{"developer_activity":1.0},"description":"Core-protocol development pace. Single-component in v0.1; expands with the GitHub adapter in Phase 2.","epistemic":"measured","kind":"supporting","name":"Development","note":"GitHub stars have low weight by design; commits alone never dominate (both are gameable).","scale":[0,10]},"evidence_confidence":{"available_in_v0_1":true,"description":"How much the numbers can be trusted, given data completeness and source quality.","epistemic":"measured","kind":"supporting","name":"Evidence Confidence","scale":[0,100]},"execution_evidence":{"available_in_v0_1":true,"components":{"developer_activity":0.3,"milestone_velocity":0.4,"setback_drag":0.3},"description":"Is the project measurably moving toward its potential? An evidence score \u2014 NOT a probability. No calibrated probabilities until historical backtesting exists (Phase 2).","epistemic":"mixed","kind":"dimension","name":"Execution Evidence","scale":[0,10]},"prove_it_age_years":{"available_in_v0_1":true,"description":"Years since network launch. Not a countdown \u2014 there is no deadline. The question is: after X years, how much closer is the thesis to fulfilled?","epistemic":"measured","kind":"supporting","name":"Prove-It Age","scale":[0,100]},"reality":{"available_in_v0_1":true,"components_note":"Weights are per thesis category (see ''categories''). Weights of unavailable components are redistributed proportionally; confidence records the gap.","description":"Genuine utility demonstrated today: willingness to pay, capital committed, thesis milestones actually achieved. Market cap is NEVER an input \u2014 price is not evidence of utility.","epistemic":"mixed","kind":"dimension","name":"Reality","scale":[0,10]},"reflexivity_risk":{"available_in_v0_1":true,"components":{"incentive_dependence":0.15,"necessity_inverse":0.2,"supply_overhang":0.25,"valuation_multiple":0.4},"description":"How dependent the current value/ecosystem is on continued speculation, incentives, issuance, or belief. High score = high dependence. Characteristics are measured; projects are never labeled.","epistemic":"mixed","kind":"dimension","name":"Reflexivity / Failure Risk","scale":[0,10]},"subsidy_dependence":{"available_in_v0_1":false,"components":{},"description":"What happens to activity when incentives end (30/90/180-day post-incentive retention). No reliable source in v0.1.","epistemic":"measured","kind":"supporting","name":"Subsidy Dependence","scale":[0,10],"unavailable_reason":"Post-incentive retention data has no reliable source in v0.1. Marked unavailable; reduces confidence."},"token_necessity":{"available_in_v0_1":true,"description":"If the token disappeared, could essentially the same protocol continue functioning? Analyst-assessed, versioned, rationale published.","epistemic":"modeling","kind":"analyst","name":"Token Necessity","scale":[0,10]},"token_value_capture":{"available_in_v0_1":true,"description":"As usage grows, does the token capture economic value? Assessed against the mechanism checklist (fees, burns, staking, collateral, settlement demand). Successful protocol != valuable token until demonstrated.","epistemic":"modeling","kind":"analyst","name":"Token Value Capture","scale":[0,10]},"world_impact_potential":{"available_in_v0_1":true,"description":"If the thesis succeeds, how consequential? Potential, not prediction. Analyst-assessed per thesis category, rationale published.","epistemic":"modeling","kind":"analyst","name":"World Impact Potential","scale":[0,10]}},"version":"0.2.0","observer_effect":{"statement":"Publishing scores can move markets. The Clock measures reflexivity risk in others; it must not become a source of it. Influence is a liability to be managed, not a goal.","goodharts_law":"When a measure becomes a target, it ceases to be a good measure. If projects ever optimize for Clock scores instead of real utility, the methodology must change \u2014 publicly, as a new version.","safeguards":[{"id":"append_only_history","text":"Score history is append-only. New methodology versions add new snapshots; past snapshots are never rewritten."},{"id":"versioned_methodology","text":"Every scoring change ships as a new versioned methodology file. Diffs are public; silent rewrites are a defect, not a feature."},{"id":"publisher_disclosure","text":"The publisher discloses positions in and promotional interest around scored tokens (see data/disclosures.json). Undisclosed holdings would make this a marketing operation, not a measurement one."},{"id":"no_tuning","text":"Algorithms calculate; nothing is tuned per-project. Every number comes from (methodology config + observations + versioned analyst seeds)."},{"id":"no_paid_placement","text":"Paid placement and sponsorship never affect rankings."}]}}'::jsonb, FALSE) ON CONFLICT (id) DO NOTHING;
